//! More python content: a project at the end of every section, plus
//! extra topic sections (each ending in its own project).
//! Hebrew for everything here is in the course's file under content/he/.

use super::*;

fn push(sections: &mut [Section], id: &str, l: Lesson) {
    sections.iter_mut().find(|s| s.id == id).unwrap_or_else(|| panic!("no section {id}")).lessons.push(l);
}

/// Insert a section after `after`, or before the final project section when `after` is None.
fn insert(sections: &mut Vec<Section>, after: Option<&str>, s: Section) {
    let at = match after {
        Some(id) => sections.iter().position(|x| x.id == id).unwrap_or_else(|| panic!("no section {id}")) + 1,
        None => sections.len() - 1,
    };
    sections.insert(at, s);
}

